        // 每四个一组：x, -(x+1), -(x+2), x+3
        for (int x = start; x <= n; x += 4) {
            res[idx++] = x;
            res[idx++] = -(x + 1);
            res[idx++] = -(x + 2);
            res[idx++] = x + 3;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
